export const BODY: string = "\n<p>ہر اچھا ڈیزائن رنگ پیلیٹ سے شروع ہوتا ہے، اور ہر اچھی پیلیٹ کہیں حقیقی سے شروع ہوتی ہے: تصویر، برانڈ تصویر، یا منظر جو پہلے سے درست لگتا ہے۔</p>\n<p>رنگ پیلیٹ ایکسٹریکٹر اس تصویر میں غالب رنگ آپ کے لیے ڈھونڈتا ہے۔ یہ پکسل اسکین کرتا ہے، انہیں اہم رنگوں میں گروپ کرتا ہے، اور سیکنڈوں میں درجہ بند پیلیٹ آپ کو دیتا ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ CompressMyPic تصویر رنگ پیلیٹ ایکسٹریکٹر کیسے کام کرتا ہے، ہر خصوصیت کیا کرتی ہے، اور تصویر کو ایسی پیلیٹ میں کیسے بدلیں جسے آپ اصل میں استعمال کر سکیں۔</p>\n<h2 id=\"what-is-a-palette-extractor\">رنگ پیلیٹ ایکسٹریکٹر کیا ہے؟</h2>\n<p>رنگ پیلیٹ ایکسٹریکٹر تصویر کا تجزیہ کرتا ہے اور اس کے سب سے اہم رنگ سویچ کے سیٹ کے طور پر واپس کرتا ہے۔ ہر سویچ رنگ، اس کی HEX، RGB اور HSL قیمتیں، اور تصویر کا وہ حصہ دکھاتا ہے جو وہ ڈھکتا ہے۔</p>\n<p>آپ تصویر اپ لوڈ کرتے ہیں، چنتے ہیں کہ آپ کو کتنے رنگ چاہییں، اور ٹول پیلیٹ بناتا ہے۔ نتیجہ تیار رنگ اسکیم ہے جو پہلے سے ایک ساتھ کام کرتی ہے، کیونکہ رنگ ایک ہی تصویر سے آئے تھے۔</p>\n<p>ٹول 20 MB تک عام تصویر فارمیٹ قبول کرتا ہے، جو فون کی تصویروں، مصنوعات شاٹ، اسکرین شاٹ اور برانڈ تصویروں کو پورا کرتا ہے۔ سب کچھ آپ کے براؤزر میں مقامی طور پر چلتا ہے، اس لیے کلائنٹ موڈ بورڈ اور غیر جاری شدہ تصور نجی رہتے ہیں۔</p>\n<h2 id=\"median-cut-quantization\">Median-Cut کوانٹائزیشن کیسے کام کرتی ہے</h2>\n<p>ایکسٹریکٹر اپنی پیلیٹ Median-Cut کوانٹائزیشن نامی الگورتھم سے بناتا ہے۔ یہ ہزاروں رنگوں کو چھوٹے نمائندہ سیٹ تک کم کرنے کی معیاری تکنیک ہے۔</p>\n<p>الگورتھم تصویر کے تمام پکسل کو ایک ڈبے میں لے کر شروع ہوتا ہے۔ یہ سب سے چوڑی حد والا رنگ چینل ڈھونڈتا ہے، ڈبے کو درمیان پر آدھا تقسیم کرتا ہے، اور تقسیم دہراتا ہے جب تک اس کے پاس اتنے ڈبے نہ ہوں جتنے آپ نے مانگے۔</p>\n<p>ہر ڈبہ پھر ایک رنگ دیتا ہے: اس کے اندر پکسل کا اوسط۔ نتیجہ رنگوں کا سیٹ ہے جو پوری تصویر کی منصفانہ نمائندگی کرتا ہے، بڑے حصوں کو اپنا سویچ ملتا ہے اور چھوٹی تفصیل ایک سویچ شیئر کرتی ہے۔</p>\n<h2 id=\"how-many-colors\">کتنے رنگ: 3 سے 12 سویچ</h2>\n<p>سلائیڈر کنٹرول کرتا ہے کہ پیلیٹ میں کتنے سویچ ہیں، 3 سے 12 تک، 6 پہلے سے طے شدہ کے ساتھ۔ گنتی پیلیٹ کی شخصیت بدلتی ہے، صرف اس کی لمبائی نہیں۔</p>\n<p>تین رنگ آپ کو کم سے کم اسکیم دیتے ہیں: غالب، ثانوی اور ایکسنٹ۔ یہ صاف ویب سائٹ، سادہ پوسٹر یا لوگو سلوک کے لیے کافی ہے۔</p>\n<p>چھ رنگ متوازن پہلے سے طے شدہ ہیں۔ یہ زیادہ تر تصویروں کے اہم لہجے پکڑتے ہیں بغیر ملتے جلتے رنگوں کو قریب نقل میں تقسیم کیے جنہیں الگ کرنا مشکل ہو۔</p>\n<h2 id=\"percentage-badges\">ہر سویچ پر فیصد بیج</h2>\n<p>ہر سویچ پر فیصد بیج ہوتا ہے جو دکھاتا ہے کہ وہ رنگ تصویر کا کتنا حصہ ڈھکتا ہے۔ 42 فیصد والا رنگ تصویر پر غالب ہے، جبکہ 3 فیصد والا چھوٹا ایکسنٹ ہے۔</p>\n<p>فیصد آپ کو پیلیٹ کی درجہ بندی بتاتے ہیں۔ سب سے بڑا رنگ عام طور پر پس منظر یا اہم موضوع ہے، اور سب سے چھوٹے وہ تفصیل ہیں جو تصویر کو اس کی شخصیت دیتے ہیں۔</p>\n<p>جب آپ ڈیزائن بنائیں تو فیصد استعمال کریں۔ عام قاعدہ یہ ہے کہ غالب رنگ کو سب سے زیادہ جگہ دیں، ثانوی رنگ کو معاون کردار، اور سب سے چھوٹے رنگوں کو صرف ایکسنٹ اور جھلکیاں۔</p>\n<h2 id=\"proportional-color-strip\">متناسب رنگ پٹی</h2>\n<p>سویچ کے نیچے ٹول متناسب رنگ پٹی دکھاتا ہے: ایک بار جو تصویر کے ہر رنگ حصے کے حساب سے حصوں میں تقسیم ہے۔ یہ تصویر کے طور پر پیلیٹ ہے۔</p>\n<p>پٹی توازن کو ایک نظر میں نظر آنے والا بناتی ہے۔ ایک بڑے حصے اور کئی چھوٹے حصوں والی تصویر مضبوط غالب رنگ اور چھوٹے ایکسنٹ والی تصویر ہے، جبکہ برابر پٹی کا مطلب مصروف، رنگین تصویر ہے۔</p>\n<p>ڈیزائنر پٹی استعمال کرتے ہیں یہ پرکھنے کے لیے کہ پیلیٹ کام کرے گی یا نہیں۔ جس پیلیٹ کی پٹی زیادہ تر ایک رنگ ہے، وہ پرسکون ڈیزائن بنائے گی، جبکہ کئی برابر حصوں والی پیلیٹ مصروف ڈیزائن بنائے گی۔</p>\n<h2 id=\"copy-css-custom-properties\">CSS کاپی کریں: ایک کلک میں کسٹم پراپرٹی</h2>\n<p>Copy CSS بٹن تمام سویچ کو ایک عمل میں CSS کسٹم پراپرٹی کے طور پر کاپی کرتا ہے۔ آپ کو --color-1 سے --color-6 جیسے متغیر ملتے ہیں، ہر ایک میں HEX قیمت ہے، اسٹائل شیٹ میں چسپاں کرنے کے لیے تیار۔</p>\n<p>یہ کوڈ ایک ایک کر کے کاپی کرنے سے تیز اور محفوظ ہے۔ برآمد ہر رنگ کو ترتیب میں رکھتی ہے، بغیر نقل غلطیوں اور بغیر گم شدہ سویچ کے۔</p>\n<p>سویچ گنتی بدلیں اور برآمد اپ ڈیٹ ہو جاتی ہے۔ آپ تصویر دوبارہ اپ لوڈ کیے بغیر 6 رنگوں سے 4 پر جا سکتے ہیں، اور کاپی شدہ CSS نیا سیٹ فوراً ظاہر کرتا ہے۔</p>\n<h2 id=\"copy-json\">JSON کاپی کریں: ڈویلپرز کے لیے ساختہ ڈیٹا</h2>\n<p>Copy JSON بٹن پیلیٹ کو ساختہ ڈیٹا کے طور پر برآمد کرتا ہے، ہر رنگ اس کی HEX، RGB اور HSL قیمتوں اور تصویر کے اس کے فیصد حصے کے ساتھ درج ہے۔</p>\n<p>JSON درست فارمیٹ ہے جب پیلیٹ اسٹائل شیٹ کی بجائے کوڈ میں جائے۔ ڈیزائن ٹوکن پائپ لائن، تھیم جنریٹر، یا ترتیب فائل، سب JSON کو سیدھا استعمال کر سکتے ہیں۔</p>\n<p>برآمد میں وہی ڈیٹا شامل ہے جو اسکرین دکھاتی ہے، ایسی شکل میں جسے اسکرپٹ پڑھ سکتا ہے۔ اس سے پیلیٹ قیمتیں دوبارہ لکھے بغیر پراجیکٹ میں دوبارہ استعمال ہوتی ہے۔</p>\n<h2 id=\"download-palette-png\">پیلیٹ PNG ڈاؤن لوڈ کریں: شیئر کرنے والا کارڈ</h2>\n<p>Download Palette PNG بٹن پیلیٹ کارڈ تصویر بناتا ہے: اصل تصویر، اس کے نیچے سویچ پٹی اور رنگ۔ یہ نکالنے کا بصری خلاصہ ہے۔</p>\n<p>کارڈ کلائنٹ یا ٹیم کے ساتھ پیلیٹ شیئر کرنے کے لیے مفید ہے۔ پیلیٹ کی تصویر HEX کوڈوں کی فہرست سے تیز بات چیت کرتی ہے، خاص طور پر ان لوگوں کے ساتھ جو کوڈ نہیں پڑھتے۔</p>\n<p>کارڈ کو موڈ بورڈ، برانڈ دستاویزات اور پریزنٹیشن میں استعمال کریں۔ یہ دکھاتا ہے کہ رنگ کہاں سے آئے، جو پیلیٹ میں اعتماد بناتا ہے، کیونکہ کلائنٹ ماخذ تصویر دیکھ سکتا ہے۔</p>\n<h2 id=\"extractor-vs-eyedropper\">ایکسٹریکٹر بمقابلہ آئی ڈراپر: مختلف سوالات</h2>\n<p>ایکسٹریکٹر اور آئی ڈراپر مختلف سوالات کا جواب دیتے ہیں۔ ایکسٹریکٹر پوچھتا ہے کہ پوری تصویر کو کون سے رنگ طے کرتے ہیں، جبکہ آئی ڈراپر پوچھتا ہے کہ یہ ایک پکسل کون سا رنگ ہے۔</p>\n<p>جب آپ کو خیالات چاہییں تو ایکسٹریکٹر استعمال کریں۔ یہ آپ کو وہ پیلیٹ دکھاتا ہے جو تصویر پہلے سے رکھتی ہے، کوریج کے حساب سے درجہ بند، اور یہ اکثر وہ رنگ ظاہر کرتا ہے جنہیں آپ آنکھ سے نہ چنتے۔</p>\n<p>جب آپ کو درستگی چاہیے تو آئی ڈراپر استعمال کریں۔ لوگو کا بالکل نیلا، بٹن کا بالکل رنگ، یا دیوار کا بالکل لہجہ، سب کو ایک پکسل پڑھنے کی ضرورت ہے۔</p>\n<h2 id=\"transparent-backgrounds\">PNG میں شفاف پس منظر</h2>\n<p>PNG فائلیں شفافیت رکھ سکتی ہیں، اور ایکسٹریکٹر اسے پیلیٹ بناتے ہوئے مکمل شفاف پکسل نظرانداز کر کے سنبھالتا ہے۔ شفاف پس منظر والا لوگو صرف اپنے نظر آنے والے رنگ دیتا ہے۔</p>\n<p>یہ اہم ہے کیونکہ شفاف حصے کا اپنا کوئی رنگ نہیں۔ اسے شامل کرنے سے جھوٹا سویچ بڑھے گا، عام طور پر سفید یا کالا، جو ڈیزائن میں کچھ ظاہر نہیں کرتا۔</p>\n<p>نیم شفاف پکسل سرمئی حصہ ہیں۔ آدھا شفاف پکسل اپنے رنگ کو اس کے پیچھے جو کچھ ہے، اس کے ساتھ ملاتا ہے، اس لیے ایکسٹریکٹر خالص رنگ کی بجائے ملا ہوا نتیجہ پڑھتا ہے۔</p>\n<h2 id=\"tiny-accents\">چھوٹا نیون ایکسنٹ کیوں نہ دکھائی دے</h2>\n<p>چھوٹا روشن ایکسنٹ پیلیٹ سے غائب ہو سکتا ہے، چاہے وہ تصویر کا سب سے یادگار حصہ ہو۔ وجہ کوریج ہے: ایکسٹریکٹر رنگوں کو اس حساب سے درجہ دیتا ہے کہ وہ تصویر کا کتنا حصہ بھرتے ہیں۔</p>\n<p>تصویر کا 1 فیصد ڈھکنے والی نیون سائن چھوٹا حصہ ہے، اس لیے الگورتھم اسے اپنا سویچ دینے کی بجائے پڑوسی رنگ میں ملا سکتا ہے۔</p>\n<p>سویچ گنتی بڑھانے سے مدد ملتی ہے۔ 12 رنگوں پر چھوٹے ایکسنٹ کو زیادہ بار اپنے ڈبے ملتے ہیں، کیونکہ الگورتھم تصویر کو باریک گروپوں میں تقسیم کرتا ہے۔</p>\n<h2 id=\"similar-shades\">دو ملتے جلتے رنگ کیوں دکھائی دیں</h2>\n<p>12 رنگوں والی پیلیٹ کبھی دو سویچ دکھاتی ہے جو تقریباً ایک جیسے لگتے ہیں۔ یہ تب ہوتا ہے جب تصویر کے بڑے حصے میں نرم گریڈینٹ ہو، جیسے آسمان جو ہلکے نیلے سے تھوڑے گہرے نیلے میں بدلتا ہے۔</p>\n<p>الگورتھم اس گریڈینٹ کو دو ڈبوں میں تقسیم کرتا ہے، اور ہر ڈبہ اپنا اوسط دیتا ہے۔ دو اوسط قریب ہیں، مگر وہ تصویر کے واقعی مختلف حصے ہیں۔</p>\n<p>جب آپ قریب نقل دیکھیں تو وہ رکھیں جو آپ کے ڈیزائن سے بہتر میل کھائے اور دوسرا ہٹا دیں۔ ایک نیلے والی پیلیٹ دو نیلوں والی پیلیٹ سے صاف ہے جنہیں کوئی الگ نہیں کر سکتا۔</p>\n<h2 id=\"privacy-local-processing\">رازداری: نکالنا آپ کے براؤزر میں ہوتا ہے</h2>\n<p>پیلیٹ نکالنے میں اکثر حساس تصویریں شامل ہوتی ہیں: کلائنٹ برانڈ تصور، غیر جاری شدہ موڈ بورڈ، اور ذاتی تصویریں۔ انہیں سرور پر اپ لوڈ کرنا ایسا خطرہ ہے جو آپ کو لینے کی ضرورت نہیں۔</p>\n<p>ایکسٹریکٹر تصویر مقامی طور پر پڑھتا ہے۔ براؤزر پکسل نمونہ لیتا ہے، کوانٹائزیشن چلاتا ہے، اور پیلیٹ بناتا ہے بغیر ایک بھی بائٹ کہیں بھیجے۔</p>\n<p>اس کا مطلب یہ بھی ہے کہ صفحہ لوڈ ہونے کے بعد ٹول آف لائن کام کرتا ہے۔ آپ ہوائی جہاز پر، میٹنگ روم میں، یا محفوظ دفتر میں بغیر کسی کنکشن کے پیلیٹ نکال سکتے ہیں۔</p>\n<h2 id=\"weighting-a-design-by-percentage\">فیصد سے ڈیزائن کو وزن دینا</h2>\n<p>فیصد بیج صرف لیبل نہیں؛ وہ ڈیزائن کی ترکیب ہیں۔ تصویر کا 45 فیصد والا رنگ لے آؤٹ کا تقریباً 45 فیصد لینا چاہیے، کیونکہ وہ تناسب ہی ہے جس نے تصویر کو متوازن محسوس کرایا۔</p>\n<p>سب سے بڑے رنگ کو پس منظر دے کر لے آؤٹ شروع کریں۔ یہ وہ رنگ ہے جسے آنکھ بڑے حصوں میں دیکھنے کی سب سے عادی ہے، اس لیے اس پر بنا صفحہ پہلی نظر سے پرسکون اور واقف لگتا ہے۔</p>\n<p>دوسرے بڑے رنگ کو اہم مواد حصوں کو دیں: کارڈ، پینل اور سیکشن۔ یہ پس منظر کو سپورٹ کرتا ہے بغیر اس سے مقابلہ کیے، اور دونوں مل کر صفحے کی ساخت بناتے ہیں۔</p>\n<h2 id=\"how-to-use-the-tool\">تصویر رنگ پیلیٹ ایکسٹریکٹر کیسے استعمال کریں</h2>\n<p><a href=\"/ur/tasveer-se-rang-palette-nikalein/\">تصویر رنگ پیلیٹ ایکسٹریکٹر</a> کھولیں اور اپنی تصویر اپ لوڈ والے حصے میں ڈالیں، یا کلپ بورڈ سے اسکرین شاٹ سیدھا چسپاں کریں۔ 20 MB تک فائلیں قبول ہوتی ہیں۔</p>\n<p>سلائیڈر منتقل کر کے 3 سے 12 سویچ کے درمیان چنیں، 6 کے پہلے سے طے شدہ سے شروع کریں۔ پیلیٹ فوراً دوبارہ بنتا ہے، فیصد اور متناسب پٹی ایک ساتھ اپ ڈیٹ ہوتے ہیں۔</p>\n<p>قدم بہ قدم ورژن کے لیے <a href=\"/ur/blog/tasveer-se-rang-palette-kaise-nikalein/\">How to Extract a Colour Palette from an Image</a> پڑھیں، اور ڈیزائن ورک فلو نکات کے لیے <a href=\"/ur/blog/photo-se-rang-palette-design/\">Colour Palettes from Photos: Design Workflow Tips</a> دیکھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ویب سائٹ پیلیٹ کے لیے بہترین رنگ تعداد کیا ہے؟","answer":"چھ اچھا پہلے سے طے شدہ ہے، اور یہ وہ عدد ہے جس سے ٹول شروع ہوتا ہے۔ یہ زیادہ تر تصویروں کے اہم لہجے پکڑتا ہے بغیر ملتے جلتے رنگوں کو نقل میں تقسیم کیے۔ کم سے کم سائٹ کے لیے 3 یا 4 رنگوں تک جائیں۔ بھرپور برانڈ نظام کے لیے 8 یا 10 تک جائیں اور قریب نقل کو ہاتھ سے ہٹا دیں۔"},{"question":"کیا ویب سائٹ کے اسکرین شاٹ سے پیلیٹ نکال سکتا ہوں؟","answer":"جی ہاں۔ اسکرین شاٹ Ctrl+V سے سیدھا چسپاں کریں یا اسکرین شاٹ فائل اپ لوڈ کریں۔ ایکسٹریکٹر انٹرفیس کے رنگوں کو درجہ دے گا، جو آپ کی پسندیدہ سائٹ کی پیلیٹ واپس لانے کا تیز طریقہ ہے۔ یاد رکھیں کہ دوسرے برانڈ کی پوری پیلیٹ نقل کرنا کلائنٹ کام کے لیے اصلیت سوالات اٹھاتا ہے۔"},{"question":"ایک ہی تصویر دوبارہ اپ لوڈ کرنے پر پیلیٹ کیوں بدلتا ہے؟","answer":"اسے نہیں بدلنا چاہیے، جب تک فائل ایک جیسی ہو۔ اگر پیلیٹ بدلتا ہے تو فائل اپ لوڈ کے درمیان شاید دوبارہ محفوظ یا دوبارہ کمپریس ہوئی، جس سے پکسل قیمتیں تھوڑی بدلتی ہیں۔ ہمیشہ اصل فائل سے نکالیں، تصویر کے اسکرین شاٹ یا دوبارہ برآمد شدہ کاپی سے نہیں۔"},{"question":"نکالی گئی پیلیٹ فگما یا کینوا میں کیسے استعمال کروں؟","answer":"سویچ سے HEX کوڈ کاپی کریں، یا Copy CSS برآمد استعمال کریں اور قیمتیں اس سے پڑھیں۔ ہر HEX کوڈ کو فگما یا کینوا میں رنگ فیلڈ میں چسپاں کریں تاکہ پیلیٹ کو رنگ سٹائل کے طور پر دوبارہ بنائیں۔ JSON برآمد مفید ہے اگر ڈویلپر اسی پیلیٹ کو کوڈ میں خود بخود لا رہا ہو۔"},{"question":"کیا ایکسٹریکٹر سیاہ سفید تصویروں پر کام کرتا ہے؟","answer":"جی ہاں، مگر پیلیٹ سرمئی رنگ ہوں گے، قریب کالے سے قریب سفید تک، فیصد دکھاتے ہوئے کہ ہر رنگ تصویر کا کتنا حصہ ڈھکتا ہے۔ یہ دراصل مفید ہے: تصویر کا سرمئی پیمانہ اس کی لہجہ ساخت ظاہر کرتا ہے، جو اس وقت مدد کرتا ہے جب آپ یک رنگ میں ڈیزائن کریں۔"},{"question":"کیا فون پر تصویر سے پیلیٹ نکال سکتا ہوں؟","answer":"جی ہاں۔ ایکسٹریکٹر iOS اور اینڈرائیڈ پر موبائل براؤزر میں چلتا ہے۔ اپنی گیلری سے تصویر اپ لوڈ کریں، سلائیڈر منتقل کر کے سویچ گنتی چنیں، اور CSS کاپی کریں یا پیلیٹ کارڈ ڈاؤن لوڈ کریں۔ ورک فلو ڈیسک ٹاپ جیسا ہی ہے۔"}];
